using System.Collections.Immutable;
using KuaiYi.Core;
using KuaiYi.Core.Settings;
using Xunit;
namespace KuaiYi.Core.Tests;
public sealed class SettingsHotkeyTests
{
    // No key is configured in this suite. Any unexpected secret access fails the test.
    private sealed class NoSecrets:ISecretProtector
    {public byte[] Protect(ReadOnlySpan<byte> plain)=>throw new InvalidOperationException("Unexpected secret access.");public byte[] Unprotect(ReadOnlySpan<byte> cipher)=>throw new InvalidOperationException("Unexpected secret access.");}
    private sealed class DirectoryPolicy:ISecretDirectoryPolicy{public void EnsurePrivate(string path)=>Directory.CreateDirectory(path);}
    private sealed class Participant(HotkeyRegistry registry):ISettingsHotkeyParticipant
    {
        private readonly HotkeyRegistry state=registry;public int Prepares,Commits,Rollbacks;public bool FailCommit;public Func<Task>? BeforePrepare;
        public async Task<ISettingsHotkeyTransaction> PrepareAsync(IReadOnlyDictionary<string,string?> values,CancellationToken cancellation)
        {Prepares++;if(BeforePrepare!=null)await BeforePrepare();cancellation.ThrowIfCancellationRequested();return new Transaction(this,state.Prepare(values));}
        private sealed class Transaction(Participant owner,HotkeyPrepared ticket):ISettingsHotkeyTransaction
        {public Task CommitAsync(SettingsSnapshot saved){owner.Commits++;if(owner.FailCommit)throw new IOException("Public injected post-publication commit failure.");owner.state.Commit(ticket,saved.Version);return Task.CompletedTask;}public Task RollbackAsync(){owner.Rollbacks++;owner.state.Rollback(ticket);return Task.CompletedTask;}}
    }
    private sealed class Fixture:IDisposable
    {
        public string Root{get;}=Path.Combine(Path.GetTempPath(),"kuaiyi-hotkey-tests-"+Guid.NewGuid().ToString("N"));public SettingsStore Store{get;}public SecretFileStore Secrets{get;}public SettingsCoordinator Coordinator{get;}public HotkeyTests.Port Port{get;}=new();public HotkeyRegistry Registry{get;}public Participant Keys{get;}
        public Fixture(){Store=new(Path.Combine(Root,"config"));Secrets=new(Path.Combine(Root,"secrets"),new NoSecrets(),new DirectoryPolicy());Coordinator=new(Store,Secrets);Registry=new(Port);Keys=new(Registry);Coordinator.Committed+=(saved,_)=>Registry.Reconcile(saved.Data.Hotkeys,saved.Version);}
        public async Task<SettingsSnapshot> Seed(){using var draft=await Coordinator.OpenDraftAsync();draft.Update(s=>s with{Hotkeys=HotkeyTests.Map(("toggle","Ctrl+Q"),("openSettings","Ctrl+W"))});return await Coordinator.SaveWithHotkeysAsync(draft,Keys);}
        public SettingsCoordinator WithWriteFault(Action<SettingsWriteStage> failure){var coordinator=new SettingsCoordinator(new(Store.DirectoryPath){WriteStageForTest=failure},Secrets);coordinator.Committed+=(saved,_)=>Registry.Reconcile(saved.Data.Hotkeys,saved.Version);return coordinator;}
        public void Dispose(){if(Directory.Exists(Root))Directory.Delete(Root,true);}
    }
    private static void Change(SettingsDraft draft)=>draft.Update(s=>s with{Hotkeys=HotkeyTests.Map(("toggle","Ctrl+T"),("openSettings","Ctrl+S"))});
    private static HotkeyDispatch Signal(Fixture f,string text)=>f.Registry.Resolve(f.Port.Owned.Single(p=>p.Value==HotkeyPolicy.Parse(text)).Key,HotkeyPolicy.Parse(text),f.Port.Now+1)!;
    [Fact]public async Task RecordingAndCancellingDraftNeverRegistersOrWrites()
    {using var f=new Fixture();var old=await f.Seed();byte[] original=await File.ReadAllBytesAsync(f.Store.PrimaryPath);f.Port.Calls.Clear();using(var draft=await f.Coordinator.OpenDraftAsync()){Change(draft);draft.Dispose();}Assert.Empty(f.Port.Calls);Assert.Equal(original,await File.ReadAllBytesAsync(f.Store.PrimaryPath));Assert.Equal(old.Version,f.Coordinator.Effective!.Version);Assert.True(f.Registry.Current(Signal(f,"Ctrl+Q")));}
    [Fact]public async Task SuccessfulSavePublishesMatchingPhysicalAndDurableMappingAndImmutableOldSnapshot()
    {using var f=new Fixture();var old=await f.Seed();var oldSignal=Signal(f,"Ctrl+Q");using var draft=await f.Coordinator.OpenDraftAsync();Change(draft);var saved=await f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys);Assert.True(draft.IsClosed);Assert.Equal("Ctrl+Q",old.Data.Hotkeys["toggle"]);Assert.Equal("Ctrl+T",saved.Data.Hotkeys["toggle"]);Assert.Equal(saved.Version,(await f.Store.LoadAsync()).Version);Assert.Equal(saved.Version,Signal(f,"Ctrl+T").SettingsVersion);Assert.False(f.Registry.Current(oldSignal));Assert.Empty(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));}
    [Theory][InlineData(SettingsWriteStage.BeforePublish,false)][InlineData(SettingsWriteStage.AfterPublish,true)]
    public async Task ActualAtomicFileBoundaryDistinguishesRollbackFromCommittedError(SettingsWriteStage at,bool committed)
    {using var f=new Fixture();var old=await f.Seed();var owned=f.Port.Owned.ToDictionary();byte[] original=await File.ReadAllBytesAsync(f.Store.PrimaryPath);var coordinator=f.WithWriteFault(stage=>{if(stage==at)throw new IOException("Public synthetic disk boundary.");});using var draft=await coordinator.OpenDraftAsync();Change(draft);if(committed){var saved=await coordinator.SaveWithHotkeysAsync(draft,f.Keys);Assert.Equal(saved.Version,Signal(f,"Ctrl+T").SettingsVersion);Assert.True(draft.IsClosed);}else{await Assert.ThrowsAsync<IOException>(()=>coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.Equal(original,await File.ReadAllBytesAsync(f.Store.PrimaryPath));Assert.Equal(old.Version,coordinator.Effective!.Version);Assert.Equal(owned.OrderBy(p=>p.Key),f.Port.Owned.OrderBy(p=>p.Key));Assert.False(draft.IsClosed);}Assert.Empty(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));}
    [Theory][InlineData(SettingsWriteStage.BeforePublish,false)][InlineData(SettingsWriteStage.AfterPublish,true)]
    public async Task CancellationAtRealFileBoundaryCannotLieAboutPublication(SettingsWriteStage at,bool committed)
    {using var f=new Fixture();var old=await f.Seed();using var cancellation=new CancellationTokenSource();var coordinator=f.WithWriteFault(stage=>{if(stage==at)cancellation.Cancel();});using var draft=await coordinator.OpenDraftAsync();Change(draft);if(committed){var saved=await coordinator.SaveWithHotkeysAsync(draft,f.Keys,cancellation:cancellation.Token);Assert.Equal(saved.Version,Signal(f,"Ctrl+T").SettingsVersion);Assert.True(draft.IsClosed);}else{await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>coordinator.SaveWithHotkeysAsync(draft,f.Keys,cancellation:cancellation.Token));Assert.Equal(old.Version,(await f.Store.LoadAsync()).Version);Assert.True(f.Registry.Current(Signal(f,"Ctrl+Q")));Assert.False(draft.IsClosed);}}
    [Fact]public async Task ThrownCancellationAfterPublicationStillCommitsNewKeys()
    {using var f=new Fixture();await f.Seed();var coordinator=f.WithWriteFault(stage=>{if(stage==SettingsWriteStage.AfterPublish)throw new OperationCanceledException("Public injected post-publication cancellation.");});using var draft=await coordinator.OpenDraftAsync();Change(draft);var saved=await coordinator.SaveWithHotkeysAsync(draft,f.Keys);Assert.Equal(saved.Version,Signal(f,"Ctrl+T").SettingsVersion);Assert.True(draft.IsClosed);}
    [Fact]public async Task OccupiedNewKeyPreservesOriginalFileKeysAndForeignOwner()
    {using var f=new Fixture();await f.Seed();byte[] original=await File.ReadAllBytesAsync(f.Store.PrimaryPath);var owned=f.Port.Owned.ToDictionary();f.Port.Foreign.Add(HotkeyPolicy.Parse("Ctrl+T"));using var draft=await f.Coordinator.OpenDraftAsync();Change(draft);var error=await Assert.ThrowsAsync<HotkeyRegistrationException>(()=>f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.Equal(1409,error.Error);Assert.Equal(original,await File.ReadAllBytesAsync(f.Store.PrimaryPath));Assert.Equal(owned.OrderBy(p=>p.Key),f.Port.Owned.OrderBy(p=>p.Key));Assert.Single(f.Port.Foreign);Assert.False(draft.IsClosed);}
    [Fact]public async Task SavedGroupSwapSurvivesNewCoordinatorAndRegistrarWithoutChangingPhysicalBindingsDuringSave()
    {using var f=new Fixture();await f.Seed();var owned=f.Port.Owned.ToDictionary();f.Port.Calls.Clear();using var draft=await f.Coordinator.OpenDraftAsync();draft.Update(s=>s with{Hotkeys=s.Hotkeys.SetItem("toggle","Ctrl+W").SetItem("openSettings","Ctrl+Q")});var saved=await f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys);Assert.Equal(owned.OrderBy(p=>p.Key),f.Port.Owned.OrderBy(p=>p.Key));Assert.DoesNotContain(f.Port.Calls,c=>c.Op is "register" or "unregister");var restarted=new SettingsCoordinator(new(f.Store.DirectoryPath),f.Secrets);using var reopened=await restarted.OpenDraftAsync();var port=new HotkeyTests.Port();var registry=new HotkeyRegistry(port);registry.Restore(reopened.Data.Hotkeys,reopened.Basis.Version);int q=port.Owned.Single(p=>p.Value==HotkeyPolicy.Parse("Ctrl+Q")).Key;Assert.Equal("openSettings",registry.Resolve(q,HotkeyPolicy.Parse("Ctrl+Q"),101)!.Action);Assert.Equal(saved.Version,reopened.Basis.Version);Assert.DoesNotContain("activation",await File.ReadAllTextAsync(f.Store.PrimaryPath),StringComparison.OrdinalIgnoreCase);}
    [Fact]public async Task CommittedButUnsettledHotkeyTransactionIsBlockedUntilActualJournalReplay()
    {using var f=new Fixture();await f.Seed();f.Keys.FailCommit=true;using var draft=await f.Coordinator.OpenDraftAsync();Change(draft);await Assert.ThrowsAsync<IOException>(()=>f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.True(draft.IsClosed);var saved=await f.Store.LoadAsync();Assert.Equal("Ctrl+T",saved.Data.Hotkeys["toggle"]);Assert.Null(Signal(f,"Ctrl+T"));Assert.Single(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));var recovery=new SettingsCoordinator(new(f.Store.DirectoryPath),f.Secrets);recovery.Committed+=(s,_)=>f.Registry.Reconcile(s.Data.Hotkeys,s.Version);using var recovered=await recovery.OpenDraftAsync();Assert.True(f.Registry.Current(Signal(f,"Ctrl+T")));Assert.Equal(saved.Version,Signal(f,"Ctrl+T").SettingsVersion);Assert.Empty(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));}
    [Fact]public async Task UnconfirmedRollbackPreservesForeignOwnerAndBlocksDispatchWithoutClaimingSave()
    {using var f=new Fixture();var old=await f.Seed();var coordinator=f.WithWriteFault(stage=>{if(stage==SettingsWriteStage.BeforePublish){f.Port.Foreign.Add(HotkeyPolicy.Parse("Ctrl+Q"));throw new IOException("Public synthetic disk failure.");}});using var draft=await coordinator.OpenDraftAsync();Change(draft);await Assert.ThrowsAsync<AggregateException>(()=>coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.Equal(old.Version,(await f.Store.LoadAsync()).Version);Assert.False(draft.IsClosed);Assert.All(f.Registry.Status,s=>Assert.True(s.RecoveryRequired));Assert.Single(f.Port.Foreign);Assert.Throws<HotkeyRegistryStateException>(()=>f.Registry.Prepare(HotkeyTests.Map()));}
    [Fact]public async Task StaleDraftFailsBeforeAnyRegistration()
    {using var f=new Fixture();await f.Seed();using var stale=await f.Coordinator.OpenDraftAsync();using(var winner=await f.Coordinator.OpenDraftAsync()){winner.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=18}});await f.Coordinator.SaveAsync(winner);}f.Port.Calls.Clear();Change(stale);await Assert.ThrowsAsync<SettingsConflictException>(()=>f.Coordinator.SaveWithHotkeysAsync(stale,f.Keys));Assert.Empty(f.Port.Calls);}
    [Fact]public async Task SaveWithoutHotkeyEditsInvalidatesOldQueuedDispatchWithoutRegistrationChurn()
    {using var f=new Fixture();await f.Seed();var old=Signal(f,"Ctrl+Q");f.Port.Calls.Clear();int prepares=f.Keys.Prepares;using var draft=await f.Coordinator.OpenDraftAsync();draft.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=18}});var saved=await f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys);Assert.Equal(prepares,f.Keys.Prepares);Assert.DoesNotContain(f.Port.Calls,c=>c.Op is "register" or "unregister");Assert.False(f.Registry.Current(old));Assert.Equal(saved.Version,Signal(f,"Ctrl+Q").SettingsVersion);}
    [Theory][InlineData("clipboard")][InlineData("endpoint")]
    public async Task HotkeyParticipantCannotGrantSensitiveConsent(string field)
    {using var f=new Fixture();await f.Seed();using var draft=await f.Coordinator.OpenDraftAsync();Change(draft);draft.Update(s=>s with{Privacy=field=="clipboard"?s.Privacy with{ClipboardAllowedApplications=["C:\\Public\\Test.exe"]}:s.Privacy with{ConsentedEndpointOrigins=["https://public.invalid:443"]}});int prepares=f.Keys.Prepares;await Assert.ThrowsAsync<SettingsValidationException>(()=>f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.Equal(prepares,f.Keys.Prepares);}
    [Fact]public async Task OriginalPrepareMustSettleBeforeCancelOrDisposeCanReleaseDraft()
    {using var f=new Fixture();await f.Seed();var entered=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var release=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);f.Keys.BeforePrepare=async()=>{entered.SetResult();await release.Task;};using var draft=await f.Coordinator.OpenDraftAsync();Change(draft);using var cancel=new CancellationTokenSource();var original=f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys,cancellation:cancel.Token);await entered.Task.WaitAsync(TimeSpan.FromSeconds(3));cancel.Cancel();Assert.False(original.IsCompleted);Assert.Throws<InvalidOperationException>(draft.Dispose);Assert.Throws<InvalidOperationException>(()=>draft.Update(s=>s));release.SetResult();await Assert.ThrowsAnyAsync<OperationCanceledException>(()=>original);Assert.False(draft.IsClosed);Assert.True(f.Registry.Current(Signal(f,"Ctrl+Q")));draft.Dispose();}
    [Fact]public async Task UnknownPublicationOutcomeRetainsPendingBindingsAndJournalInsteadOfGuessingRollback()
    {using var f=new Fixture();await f.Seed();var coordinator=f.WithWriteFault(stage=>{if(stage==SettingsWriteStage.AfterPublish){var data=SettingsJson.Read(File.ReadAllBytes(f.Store.PrimaryPath),out _) with{WriteId=Guid.NewGuid()};File.WriteAllBytes(f.Store.PrimaryPath,SettingsJson.Write(data));throw new IOException("Public concurrent publication uncertainty.");}});using var draft=await coordinator.OpenDraftAsync();Change(draft);await Assert.ThrowsAsync<SettingsTransactionUnconfirmedException>(()=>coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.False(draft.IsClosed);Assert.Equal(0,f.Keys.Rollbacks);Assert.Equal("Ctrl+T",(await f.Store.LoadAsync()).Data.Hotkeys["toggle"]);Assert.Null(Signal(f,"Ctrl+T"));Assert.Single(Directory.GetFiles(f.Store.DirectoryPath,"secret-txn-*.json"));Assert.Throws<HotkeyRegistryStateException>(()=>f.Registry.Prepare(HotkeyTests.Map()));}
    [Theory][InlineData(SettingsRecovery.UseBackup)][InlineData(SettingsRecovery.UseDefaults)]
    public async Task ExplicitRecoveryChoiceEditsAndSavesItsActualHotkeyDraft(SettingsRecovery choice)
    {
        using var f=new Fixture();await f.Seed();using(var next=await f.Coordinator.OpenDraftAsync()){next.Update(s=>s with{Overlay=s.Overlay with{FontSizeDip=18}});await f.Coordinator.SaveAsync(next);}await File.WriteAllTextAsync(f.Store.PrimaryPath,"{public-corrupt");
        using var recovery=new SettingsRecoveryDraft(await f.Coordinator.OpenDraftAsync());Assert.True(recovery.Select(choice));recovery.Draft.Update(s=>s with{Hotkeys=s.Hotkeys.SetItem("openSettings","Alt+K")});var saved=await recovery.SaveAsync(f.Coordinator,hotkeys:f.Keys);Assert.Equal("Alt+K",saved.Data.Hotkeys["openSettings"]);Assert.Equal(saved.Version,Signal(f,"Alt+K").SettingsVersion);Assert.Equal(choice==SettingsRecovery.UseDefaults?6:2,f.Port.Owned.Count);Assert.Single(Directory.GetFiles(f.Store.DirectoryPath,"settings.corrupt-*.json"));Assert.Equal("{public-corrupt",await File.ReadAllTextAsync(Directory.GetFiles(f.Store.DirectoryPath,"settings.corrupt-*.json").Single()));
    }
    [Fact]public async Task CancellingRecoveryChoiceDoesNotApplyDefaultKeysOrOverwriteCorruption()
    {using var f=new Fixture();await f.Seed();await File.WriteAllTextAsync(f.Store.PrimaryPath,"{public-corrupt");using var recovery=new SettingsRecoveryDraft(await f.Coordinator.OpenDraftAsync());f.Port.Calls.Clear();Assert.True(recovery.Select(SettingsRecovery.UseDefaults));recovery.Draft.Update(s=>s with{Hotkeys=s.Hotkeys.SetItem("toggle","Ctrl+K")});recovery.Dispose();Assert.Empty(f.Port.Calls);Assert.Equal("{public-corrupt",await File.ReadAllTextAsync(f.Store.PrimaryPath));Assert.True(f.Registry.Current(Signal(f,"Ctrl+Q")));}
    [Fact]public async Task InvalidDuplicateSettingsAreRejectedBeforeRegistrationAndRemainRecoverableOnDisk()
    {using var f=new Fixture();await f.Seed();using var draft=await f.Coordinator.OpenDraftAsync();draft.Update(s=>s with{Hotkeys=HotkeyTests.Map(("toggle","Ctrl+Q"),("openSettings","control+q"))});int prepares=f.Keys.Prepares;await Assert.ThrowsAsync<SettingsValidationException>(()=>f.Coordinator.SaveWithHotkeysAsync(draft,f.Keys));Assert.Equal(prepares,f.Keys.Prepares);}
}
